import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { llmEvaluationsLogic } from './evaluations/llmEvaluationsLogic'
import { EvaluationConfig, EvaluationRun } from './evaluations/types'
import { queryEvaluationRuns } from './utils'

export interface GenerationEvaluationRunsLogicProps {
    traceId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface generationEvaluationRunsLogicValues {
    evaluations: EvaluationConfig[] // llmEvaluationsLogic
    evaluationsLoading: boolean // llmEvaluationsLogic
    generationEvaluationRuns: EvaluationRun[]
    generationEvaluationRunsLoading: boolean
    isForceRefresh: boolean
    runnableEvaluations: EvaluationConfig[]
    selectedEvaluation: EvaluationConfig | null
    selectedEvaluationId: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface generationEvaluationRunsLogicActions {
    loadGenerationEvaluationRuns: () => any
    loadGenerationEvaluationRunsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadGenerationEvaluationRunsSuccess: (
        generationEvaluationRuns: EvaluationRun[],
        payload?: any
    ) => {
        generationEvaluationRuns: EvaluationRun[]
        payload?: any
    }
    refreshGenerationEvaluationRuns: () => {
        value: true
    }
    setSelectedEvaluationId: (evaluationId: string | null) => {
        evaluationId: string | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface generationEvaluationRunsLogicMeta {
    key: string
}

export type generationEvaluationRunsLogicType = MakeLogicType<
    generationEvaluationRunsLogicValues,
    generationEvaluationRunsLogicActions,
    GenerationEvaluationRunsLogicProps,
    generationEvaluationRunsLogicMeta
>

export const generationEvaluationRunsLogic = kea<generationEvaluationRunsLogicType>([
    path(['products', 'ai_observability', 'frontend', 'generationEvaluationRunsLogic']),
    props({} as GenerationEvaluationRunsLogicProps),
    key((props) => `trace-${props.traceId}`),
    connect(() => ({
        values: [llmEvaluationsLogic, ['evaluations', 'evaluationsLoading']],
    })),

    actions({
        refreshGenerationEvaluationRuns: true,
        setSelectedEvaluationId: (evaluationId: string | null) => ({ evaluationId }),
    }),

    loaders(({ props, values }) => ({
        generationEvaluationRuns: [
            [] as EvaluationRun[],
            {
                loadGenerationEvaluationRuns: async () => {
                    try {
                        return await queryEvaluationRuns({
                            traceId: props.traceId,
                            forceRefresh: values.isForceRefresh,
                        })
                    } catch (error) {
                        console.error('Failed to load generation evaluation runs:', error)
                        return []
                    }
                },
            },
        ],
    })),

    reducers({
        isForceRefresh: [
            false,
            {
                refreshGenerationEvaluationRuns: () => true,
                loadGenerationEvaluationRunsSuccess: () => false,
                loadGenerationEvaluationRunsFailure: () => false,
            },
        ],
        selectedEvaluationId: [
            null as string | null,
            {
                setSelectedEvaluationId: (_, { evaluationId }) => evaluationId,
            },
        ],
    }),

    selectors({
        // A manual run pushes one generation through the generation workflow, so the endpoint
        // rejects a trace- or session-target evaluation with a 400.
        runnableEvaluations: [
            (s) => [s.evaluations],
            (evaluations: EvaluationConfig[]): EvaluationConfig[] =>
                evaluations.filter((evaluation) => !evaluation.deleted && evaluation.target === 'generation'),
        ],
        // The stored id outlives the list it was picked from, because an evaluation can be deleted
        // or retargeted while this tab stays open. Read the selection back through the runnable
        // list so a stale id cannot reach the endpoint.
        selectedEvaluation: [
            (s) => [s.runnableEvaluations, s.selectedEvaluationId],
            (runnableEvaluations: EvaluationConfig[], selectedEvaluationId: string | null): EvaluationConfig | null =>
                runnableEvaluations.find((evaluation) => evaluation.id === selectedEvaluationId) ?? null,
        ],
    }),

    listeners(({ actions }) => ({
        refreshGenerationEvaluationRuns: () => {
            actions.loadGenerationEvaluationRuns()
        },
    })),

    afterMount(({ actions }) => {
        actions.loadGenerationEvaluationRuns()
    }),
])
